import { GET_CLIENTS } from "./types";
import { tokenConfig } from "./authActions";
import { returnErrors } from "./errorActions";
import axios from "axios";

export const getClients = () => dispatch => {
  axios
    .get("/api/items")
    .then(res =>
      dispatch({
        type: GET_CLIENTS,
        payload: res.data
      })
    )
    .catch(err => console.log(err));
};
